func removeForcedOutputDir(path, repoDir string) error {
	abs, err := filepath.Abs(path)
	if err != nil {
		return fmt.Errorf("resolve forced output directory: %w", err)
	}
	info, err := os.Lstat(abs)
	if err != nil {
		if os.IsNotExist(err) {
			return nil
		}
		return fmt.Errorf("stat forced output directory: %w", err)
	}
	if info.Mode()&os.ModeSymlink != 0 {
		return fmt.Errorf("forced output directory must not be a symlink: %s", abs)
	}
	if !info.IsDir() {
		return fmt.Errorf("forced output path exists and is not a directory: %s", abs)
	}
	if err := rejectDangerousForcedOutputDir(abs, repoDir); err != nil {
		return err
	}
	resolved, err := filepath.EvalSymlinks(abs)
	if err != nil {
		return fmt.Errorf("resolve forced output symlinks: %w", err)
	}
	if !sameCleanPath(abs, resolved) {
		if err := rejectDangerousForcedOutputDir(resolved, repoDir); err != nil {
			return err
		}
	}
	manifestPath := filepath.Join(abs, bmanifest.FileName)
	manifestInfo, err := os.Lstat(manifestPath)
	if err != nil {
		if os.IsNotExist(err) {
			return fmt.Errorf("--force refuses to remove %s: missing %s", abs, bmanifest.FileName)
		}
		return fmt.Errorf("stat forced output manifest: %w", err)
	}
	if manifestInfo.Mode()&os.ModeSymlink != 0 {
		return fmt.Errorf("--force refuses to remove %s: %s must not be a symlink", abs, bmanifest.FileName)
	}
	data, err := os.ReadFile(manifestPath)
	if err != nil {
		return fmt.Errorf("read forced output manifest: %w", err)
	}
	if err := validateForcedOutputManifest(data); err != nil {
		return fmt.Errorf("--force refuses to remove %s: invalid %s: %w", abs, bmanifest.FileName, err)
	}
	if err := removeAllWithRetry(abs); err != nil {
		return fmt.Errorf("remove forced output directory: %w", err)
	}
	return nil
}

func validateForcedOutputManifest(data []byte) error {
	var manifest exportManifest
	if err := json.Unmarshal(data, &manifest); err != nil {
		return err
	}
	bmanifest.Normalize(&manifest)
	// A floor, not a range. This explicit-output --force path exists only to
	// confirm the target directory holds a genuine prior brain/export before
	// wiping it, not to gate on whether THIS build can read everything the
	// manifest contains. A manifest from a NEWER build still proves that: it
	// is a real manifest this build cannot parse further, and --force is the
	// deliberate destructive discard-and-rebuild escape hatch -- the only
	// recovery available for exactly that case. Rejecting it here, the way
	// equality once did, would make --force refuse the one case it exists for.
	// Only a version below the oldest this build ever reads fails the "is this
	// a brain store" check.
	if manifest.SchemaVersion < bmanifest.MinSchemaVersion {
		return fmt.Errorf("schema_version %d is older than the first supported version %d", manifest.SchemaVersion, bmanifest.MinSchemaVersion)
	}
	if manifest.Sources == nil {
		return errors.New("missing sources")
	}
	if manifest.Sources.Sessions != nil ||
		manifest.Sources.Seed != nil ||
		manifest.Sources.Semantic != nil ||
		manifest.Sources.History != nil ||
		manifest.Sources.Facts != nil ||
		manifest.Sources.Docs != nil {
		return nil
	}
	return errors.New("missing recognized brain sources")
}

func removeAllWithRetry(path string) error {
	var lastErr error
	for i := 0; i < 5; i++ {
		if err := os.RemoveAll(path); err != nil {
			lastErr = err
			time.Sleep(time.Duration(i+1) * 25 * time.Millisecond)
			continue
		}
		return nil
	}
	return lastErr
}

